script:
(function () {
  'use strict';
  // Discounted cash flow (DCF) business valuation.
  //   Base-year free cash flow (FCF) = entered directly, or operating profit x (1 - tax rate)
  //     + depreciation and amortization - capital expenditures - increase in working capital.
  //   Projected FCF_t = base x (1 + g)^t for t = 1..N, unless year-by-year values are entered.
  //   PV_t = FCF_t / (1 + r)^t  (or ^(t - 0.5) with the mid-year convention).
  //   Terminal value at year N: Gordon growth TV = FCF_N x (1 + g_t) / (r - g_t), or
  //     exit multiple TV = multiple x EBITDA_N (EBITDA grows at the projection rate).
  //     Discounted from the end of year N: PV(TV) = TV / (1 + r)^N.
  //   Enterprise value = sum PV_t + PV(TV); equity value = EV - debt + cash; per share = equity / shares.
  //   Cross-checks: implied exit multiple TV / EBITDA_N; implied perpetual growth from an exit-multiple
  //     TV: g = (TV x r - FCF_N) / (TV + FCF_N).
  // Verified (Node, scratch tests, against hand calculations):
  //   FCF $100 for 5 years flat (g = 0), r = 10%, no terminal (g_t = 0 and Gordon gives 100/0.1 = 1,000):
  //     PV of FCFs = 100 x annuity factor 3.790787 = $379.08; PV(TV) = 1,000 / 1.1^5 = $620.92;
  //     EV = $1,000.00 (a level perpetuity is worth FCF / r, as it should be).
  //   Growing perpetuity check: base $100, g = g_t = 3%, r = 10% -> EV = 100 x 1.03 / 0.07 = $1,471.43.
  //   Defaults: EBIT $1.5M, 21% tax, D&A $200k, capex $300k, working capital $50k -> base FCF $1,035,000.
  //   Mid-year convention multiplies each PV_t by 1.1^0.5 = 1.048809 at r = 10% (checked: $436 -> $457).
  //   Exit multiple: EBITDA $1.7M grown 5% for 5 years = $2,169,678.66; x 10 = TV $21,696,786.56.
  //
  var money = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 0 });
  var cents = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', minimumFractionDigits: 2, maximumFractionDigits: 2 });

  function el(id) { return document.getElementById(id); }
  function raw(id) { return el(id).value.trim() === '' ? 0 : parseFloat(el(id).value); }
  function ok(v) { return typeof v === 'number' && isFinite(v); }
  function pct(x) { return (x * 100).toFixed(2).replace(/\.?0+$/, '') + '%'; }

  // Parses a list of yearly amounts separated by semicolons or new lines ("1,200,000; 1,300,000").
  // Returns null when any entry is not a number.
  function parseList(text) {
    var parts = text.split(/[;\n]+/), out = [];
    for (var i = 0; i < parts.length; i++) {
      var p = parts[i].replace(/[$,\s]/g, '');
      if (p === '') continue;
      var v = Number(p);
      if (!isFinite(v)) return null;
      out.push(v);
    }
    return out;
  }

  function value(o) {
    var flows = [], ebitda = [], f = o.baseFcf, e = o.baseEbitda;
    var n = o.custom ? o.custom.length : o.years;
    for (var t = 1; t <= n; t++) {
      f = f * (1 + o.growth); e = e * (1 + o.growth);
      flows.push(o.custom ? o.custom[t - 1] : f);
      ebitda.push(e);
    }
    var rows = [], pvSum = 0;
    for (var k = 0; k < n; k++) {
      var period = o.midYear ? k + 0.5 : k + 1;
      var df = 1 / Math.pow(1 + o.rate, period);
      rows.push({ year: k + 1, fcf: flows[k], df: df, pv: flows[k] * df });
      pvSum += flows[k] * df;
    }
    var last = flows[n - 1], lastEbitda = ebitda[n - 1], tv;
    if (o.method === 'gordon') tv = last * (1 + o.termGrowth) / (o.rate - o.termGrowth);
    else tv = o.multiple * lastEbitda;
    var pvTv = tv / Math.pow(1 + o.rate, n);
    var ev = pvSum + pvTv, equity = ev - o.debt + o.cash;
    var impliedGrowth = (tv + last) !== 0 ? (tv * o.rate - last) / (tv + last) : NaN;
    return { rows: rows, pvSum: pvSum, tv: tv, pvTv: pvTv, ev: ev, equity: equity, last: last, n: n,
             lastEbitda: lastEbitda, impliedGrowth: impliedGrowth, tvDf: 1 / Math.pow(1 + o.rate, n) };
  }

  function cell(text) { var td = document.createElement('td'); td.textContent = text; return td; }
  function fail(msg) { var e = el('dcError'); e.hidden = false; e.textContent = msg; }

  function update() {
    var mode = el('dcMode').value, method = el('dcMethod').value;
    var build = mode === 'build', exit = method === 'exit';
    el('dcDirectWrap').hidden = build;
    el('dcBuildWrap').hidden = !build;
    el('dcGordonWrap').hidden = exit;
    el('dcExitWrap').hidden = !exit;
    el('dcEbitdaWrap').hidden = !(exit && !build);

    var o = {
      method: method, growth: raw('dcGrowth') / 100, years: Math.round(raw('dcYears')), rate: raw('dcRate') / 100,
      termGrowth: raw('dcTermGrowth') / 100, multiple: raw('dcMultiple'), debt: raw('dcDebt'), cash: raw('dcCash'),
      shares: raw('dcShares'), midYear: el('dcMidYear').checked, custom: null
    };
    var ebit = raw('dcEbit'), tax = raw('dcTax') / 100, da = raw('dcDa'), capex = raw('dcCapex'), nwc = raw('dcNwc');
    if (build) { o.baseFcf = ebit * (1 - tax) + da - capex - nwc; o.baseEbitda = ebit + da; }
    else { o.baseFcf = raw('dcFcf'); o.baseEbitda = raw('dcEbitda'); }

    var listText = el('dcCustom').value.trim();
    if (listText !== '') {
      o.custom = parseList(listText);
      if (!o.custom || o.custom.length === 0 || o.custom.length > 30) return fail('Enter 1 to 30 yearly cash flows as numbers separated by semicolons or new lines.');
    }
    var all = [o.growth, o.years, o.rate, o.termGrowth, o.multiple, o.debt, o.cash, o.shares, o.baseFcf, o.baseEbitda, ebit, tax, da, capex, nwc];
    if (!all.every(ok)) return fail('Fill in every field with a number.');
    if (!o.custom && (o.years < 1 || o.years > 30)) return fail('Use a projection period of 1 to 30 years.');
    if (o.rate <= -0.99 || o.rate > 1 || o.growth <= -1 || o.growth > 1) return fail('Use a discount rate and growth rate between -99% and 100%.');
    if (tax < 0 || tax >= 1) return fail('Use a tax rate from 0% up to 100%.');
    if (o.debt < 0 || o.cash < 0 || o.shares < 0 || o.multiple < 0) return fail('Debt, cash, shares and the exit multiple cannot be negative.');
    if (method === 'gordon' && o.termGrowth >= o.rate) return fail('The terminal growth rate must be lower than the discount rate, or the value would be infinite.');
    el('dcError').hidden = true;

    var r = value(o);
    var vals = [r.ev, r.equity, r.pvSum, r.pvTv, r.tv];
    if (!vals.every(ok)) return fail('These inputs produce a value too large to show. Check the rates and amounts.');

    el('dcEquity').textContent = money.format(r.equity);
    el('dcPerShare').textContent = o.shares > 0 ? cents.format(r.equity / o.shares) : '–';
    el('dcEv').textContent = money.format(r.ev);
    el('dcBaseFcf').textContent = money.format(o.baseFcf);
    el('dcPvFlows').textContent = money.format(r.pvSum);
    el('dcTv').textContent = money.format(r.tv);
    el('dcPvTv').textContent = money.format(r.pvTv) + (r.ev > 0 ? ' (' + pct(r.pvTv / r.ev) + ' of value)' : '');
    el('dcNetDebt').textContent = money.format(o.debt - o.cash);
    var cross = el('dcCross'), crossLabel = el('dcCrossLabel');
    if (method === 'gordon') {
      crossLabel.textContent = 'Implied exit multiple of final-year ' + (build ? 'EBITDA' : 'free cash flow');
      var denom = build ? r.lastEbitda : r.last;
      cross.textContent = denom > 0 ? (r.tv / denom).toFixed(1) + '×' : '–';
    } else {
      crossLabel.textContent = 'Implied perpetual growth rate';
      cross.textContent = ok(r.impliedGrowth) && r.last > 0 ? pct(r.impliedGrowth) : '–';
    }
    var note = el('dcNote'), msgs = [];
    if (r.ev < 0) msgs.push('The enterprise value is negative because the projected cash flows are negative.');
    else if (r.equity < 0) msgs.push('Net debt is larger than the enterprise value, so the equity value is negative.');
    if (r.ev > 0 && r.pvTv / r.ev > 0.75) msgs.push('More than three quarters of the value comes from the terminal value, so the result is very sensitive to the terminal assumptions.');
    note.hidden = msgs.length === 0;
    note.textContent = msgs.join(' ');

    var body = el('dcSchedule');
    while (body.firstChild) body.removeChild(body.firstChild);
    r.rows.forEach(function (row) {
      var tr = document.createElement('tr');
      tr.appendChild(cell(String(row.year)));
      tr.appendChild(cell(money.format(row.fcf)));
      tr.appendChild(cell(row.df.toFixed(4)));
      tr.appendChild(cell(money.format(row.pv)));
      body.appendChild(tr);
    });
    var tr = document.createElement('tr');
    tr.className = 'font-semibold';
    tr.appendChild(cell('Terminal value (end of year ' + r.n + ')'));
    tr.appendChild(cell(money.format(r.tv)));
    tr.appendChild(cell(r.tvDf.toFixed(4)));
    tr.appendChild(cell(money.format(r.pvTv)));
    body.appendChild(tr);
  }

  document.addEventListener('DOMContentLoaded', function () {
    var form = el('dcForm');
    form.addEventListener('input', update);
    form.addEventListener('change', update);
    form.addEventListener('submit', function (e) { e.preventDefault(); });
    update();
  });
})();
